# Hoot installer bootstrap, kit v0.1.0 (generated by `rummage installer pack`, CLDMV/rummage#472).
#
#   irm https://cldmv.github.io/hoot-install/install.ps1 | iex
#
# It only makes sure a Node runtime exists, then runs the installer. Every download is pinned by SHA-256 in this file
# and checked before anything from it runs; a mismatch stops the install. Nothing here is secret.
#
# Options (environment): HOOT_HOME, HOOT_PORT, HOOT_VERSION, HOOT_SETUP_TOKEN, HOOT_GPU,
# HOOT_REGISTRY_TOKEN, HOOT_YES.

# Everything is inside one script block, invoked on the last line, so a download cut short runs nothing.
& {
	$ErrorActionPreference = 'Stop'
	$ProgressPreference = 'SilentlyContinue'
	[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12

	$appHome = $env:HOOT_HOME
	if (-not $appHome) { $appHome = Join-Path $env:LOCALAPPDATA 'Hoot' }
	$installerUrl = 'https://cldmv.github.io/hoot-install/v0.1.0/installer.tgz'
	$installerSha256 = 'a71cfa49c15be8b6edb037a9033f64a14f8f6e5cd3438d77f66cc50ae243c8fb'
	$nodeVersion = '24.22.2'
	$nodeMinMajor = 20

	# Never `exit`: under `irm | iex` that would close the person's PowerShell window.
	function Fail($msg) { throw "! $msg" }
	function Get-Verified($url, $dest, $sha256) {
		Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $dest
		$got = (Get-FileHash -Algorithm SHA256 -Path $dest).Hash.ToLowerInvariant()
		if ($got -ne $sha256) { Remove-Item -Force $dest; Fail "checksum mismatch for $(Split-Path -Leaf $dest): expected $sha256, got $got. Nothing was run." }
	}

	New-Item -ItemType Directory -Force -Path $appHome | Out-Null

	# A Node runtime: the system's when it is new enough, else a pinned portable one in the app folder.
	$node = $null
	$sys = Get-Command node -ErrorAction SilentlyContinue
	if ($sys) {
		$major = 0
		try { $major = [int](& $sys.Source -p "process.versions.node.split('.')[0]") } catch { $major = 0 }
		if ($major -ge $nodeMinMajor) { $node = $sys.Source }
	}
	if (-not $node) {
		switch ($env:PROCESSOR_ARCHITECTURE) {
			'AMD64' { $nodeFile = 'node-v24.22.2-win-x64.zip'; $nodeSha256 = 'ca1bff5d8ead13c9f2ea404a176db46bd430704d5b5113734049fa365e7799e2' }
			'ARM64' { $nodeFile = 'node-v24.22.2-win-arm64.zip'; $nodeSha256 = 'f47968c213105077f64c6510f007632c0ca2574802a0b5067c327c49abe1c468' }
			default { Fail "no pinned Node runtime for $($env:PROCESSOR_ARCHITECTURE); install Node $nodeMinMajor or newer and run: npx @cldmv/hoot-install" }
		}
		$nodeDir = Join-Path $appHome "node\$nodeVersion"
		if (-not (Test-Path (Join-Path $nodeDir 'node.exe'))) {
			Write-Host "Downloading Node $nodeVersion ($nodeFile)..."
			$nodeRoot = Join-Path $appHome 'node'
			New-Item -ItemType Directory -Force -Path $nodeRoot | Out-Null
			$zip = Join-Path $nodeRoot $nodeFile
			Get-Verified "https://nodejs.org/dist/v$nodeVersion/$nodeFile" $zip $nodeSha256
			$tmp = "$nodeDir.tmp"
			if (Test-Path $tmp) { Remove-Item -Recurse -Force $tmp }
			Expand-Archive -Path $zip -DestinationPath $tmp
			Remove-Item -Force $zip
			if (Test-Path $nodeDir) { Remove-Item -Recurse -Force $nodeDir }
			Move-Item (Join-Path $tmp ([IO.Path]::GetFileNameWithoutExtension($nodeFile))) $nodeDir
			Remove-Item -Recurse -Force $tmp
		}
		$node = Join-Path $nodeDir 'node.exe'
	}

	# The installer itself, pinned by hash (tar.exe ships with Windows 10 1803 and later).
	$dir = Join-Path $appHome "installer\$installerSha256"
	if (-not (Test-Path (Join-Path $dir 'installer\bin\install.mjs'))) {
		$root = Join-Path $appHome 'installer'
		New-Item -ItemType Directory -Force -Path $root | Out-Null
		$archive = Join-Path $root "installer-$installerSha256.tgz"
		Get-Verified $installerUrl $archive $installerSha256
		$tmp = "$dir.tmp"
		if (Test-Path $tmp) { Remove-Item -Recurse -Force $tmp }
		New-Item -ItemType Directory -Force -Path $tmp | Out-Null
		tar.exe -xzf $archive -C $tmp
		if ($LASTEXITCODE -ne 0) { Fail "could not unpack the installer" }
		Remove-Item -Force $archive
		if (Test-Path $dir) { Remove-Item -Recurse -Force $dir }
		Move-Item $tmp $dir
	}

	& $node (Join-Path $dir 'installer\bin\install.mjs')
	if ($LASTEXITCODE -ne 0) { Write-Host "The installer stopped (exit $LASTEXITCODE); its log is in $appHome\install.log" }
}
